from tri import build
A = ['uk', 'pl', 'en']
build(11, dict(
 title='Чий кинджал?|Czyj sztylet?|Whose Dagger?',
 scene='Кейтлін таємно прибуває до столиці. Мізинець, який колись був закоханий у неї, ховає її у своєму домі в місті й кличе Неда. Він упізнає кинджал: колись той належав йому, але він програв його в парі на турнірі — Тіріону Ланністеру. Нед і Кейтлін тепер певні, що за нападом стоять Ланністери. Кейтлін вирушає додому, а Нед починає власне розслідування.|Catelyn potajemnie przybywa do stolicy. Littlefinger, który kiedyś był w niej zakochany, ukrywa ją w swoim domu w mieście i wzywa Neda. Rozpoznaje sztylet: kiedyś należał do niego, ale przegrał go w zakładzie na turnieju — z Tyrionem Lannisterem. Ned i Catelyn są teraz pewni, że za napaścią stoją Lannisterowie. Catelyn wraca do domu, a Ned zaczyna własne śledztwo.|Catelyn arrives secretly in the capital. Littlefinger, who was once in love with her, hides her in a house of his in the city and sends for Ned. He recognises the dagger: it used to be his, but he lost it in a bet at a tournament, to Tyrion Lannister. Ned and Catelyn are now sure the Lannisters are behind the attack. Catelyn sets off for home, and Ned begins his own investigation.',
 prev='На першому засіданні малої ради Нед дізнався, що корона винна Ланністерам мільйони, а король хоче турнір. Мізинець перевіряв тебе в коридорі. Тим часом корабель Кейтлін наближається до столиці.|Na pierwszym posiedzeniu małej rady Ned dowiedział się, że korona jest winna Lannisterom miliony, a król chce turnieju. Littlefinger sprawdzał cię na korytarzu. Tymczasem statek Catelyn zbliża się do stolicy.|At the first small council meeting Ned learned that the crown owes the Lannisters millions and the king wants a tournament. Littlefinger tested you in the corridor. Meanwhile Catelyn\'s ship is approaching the capital.',
 cards=[('Кейтлін Старк', 'Catelyn Stark', 'Приїхала таємно з кинджалом убивці. Хоче правди, а не помсти — поки що.|Przyjechała potajemnie ze sztyletem zabójcy. Chce prawdy, nie zemsty — na razie.|She has come secretly with the assassin\'s dagger. She wants the truth, not revenge — for now.'),
        ('Петир Бейліш', 'Petyr Baelish', 'Виріс разом із Кейтлін у Ріверрані. Каже, що хоче допомогти.|Dorastał razem z Catelyn w Riverrun. Mówi, że chce pomóc.|He grew up with Catelyn at Riverrun. He says he wants to help.'),
        ('Варис', 'Varys', 'Знайшов Кейтлін раніше, ніж будь-хто. Як — ніхто не знає.|Znalazł Catelyn wcześniej niż ktokolwiek. Jak — nikt nie wie.|He found Catelyn before anyone else did. How, no one knows.'),
        ('Сер Родрік Кассель', 'Ser Rodrik Cassel', 'Привіз Кейтлін до столиці. Відвезе її додому через Королівський тракт.|Przywiózł Catelyn do stolicy. Odwiezie ją do domu Królewskim Traktem.|He brought Catelyn to the capital. He will take her home by the Kingsroad.'),
        ('Нед Старк', 'Ned Stark', 'Тепер знає більше, ніж хотів би. Починає шукати, що відкрив Джон Аррен.|Teraz wie więcej, niż by chciał. Zaczyna szukać tego, co odkrył Jon Arryn.|He now knows more than he would like. He starts to look for what Jon Arryn discovered.')],
 gname={'en': 'Third and mixed conditionals: if + past perfect, would have; mixed time|Trzeci i mieszany okres warunkowy|Third and mixed conditionals',
        'pl': 'Warunek nierealny w przeszłości: gdyby wtedy… + -łby; mieszane czasy|Warunek nierealny w przeszłości|Polish unreal past conditions',
        'uk': 'Нереальна умова в минулому: якби тоді… + би; змішані часи|Nierealny warunek w przeszłości po ukraińsku|Ukrainian unreal past conditions'},
 where='Ти в маленькій кімнаті над крамницею в Королівській Гавані, зачинені віконниці.|Jesteś w małym pokoju nad sklepem w Królewskiej Przystani, okiennice zamknięte.|You are in a small room above a shop in King\'s Landing, with the shutters closed.',
 role='Лорд Нед узяв тебе з собою на таємну зустріч, бо тільки ти бачив лист Лізи. У маленькій кімнаті над крамницею чекає леді Кейтлін. Ти тримаєш свічку і слухаєш розмову, від якої залежить майбутнє родини Старків.|Lord Ned zabrał cię na tajne spotkanie, bo tylko ty widziałeś list Lysy. W małym pokoju nad sklepem czeka lady Catelyn. Trzymasz świecę i słuchasz rozmowy, od której zależy przyszłość Starków.|Lord Ned has brought you to a secret meeting because only you saw Lysa\'s letter. Lady Catelyn is waiting in a small room above a shop. You hold the candle and listen to a conversation on which the Starks\' future depends.',
 sc=[('Таємна зустріч|Tajne spotkanie|The secret meeting', 'зустріч|spotkanie|meeting;сховати|ukryć|to hide;упізнати|rozpoznać|to recognise;хвилюватися|martwić się|to worry;обійматися|obejmować się|to embrace;двері|drzwi|door', [
   'Мізинець [сховав/сховає/ховаючи] Кейтлін у своєму домі ще вранці.|Littlefinger [ukrył/ukryje/ukrywając] Catelyn w swoim domu już rano.|Littlefinger [had hidden/has hide/hides] Catelyn in his house that morning.',
   'Якби Варис не знайшов її, Нед [не прийшов би/не прийде/не приходячи] так швидко.|Gdyby Varys jej nie znalazł, Ned [nie przyszedłby/nie przyjdzie/nie przychodząc] tak szybko.|If Varys hadn\'t found her, Ned [wouldn\'t have come/won\'t come/doesn\'t come] so quickly.',
   'Нед і Кейтлін довго [обіймалися] мовчки.|Ned i Catelyn długo [obejmowali się] w milczeniu.|Ned and Catelyn [embraced] for a long time in silence.',
   'Ти стоїш біля [дверей] зі свічкою.|Stoisz przy [drzwiach] ze świecą.|You are standing by the [door] with a candle.',
   'Ця [зустріч] має лишитися таємницею.|To [spotkanie] musi pozostać tajemnicą.|This [meeting] must remain a secret.',
   'Кейтлін [хвилюється]: що, як за ними стежать?|Catelyn się [martwi]: a jeśli ktoś ich śledzi?|Catelyn [is worried]: what if someone is following them?']),
  ('Кинджал|Sztylet|The dagger', 'лезо|ostrze|blade;руків\'я|rękojeść|handle;сталь|stal|steel;пара|zakład|bet;програти|przegrać|to lose;власник|właściciel|owner', [
   'Кейтлін кладе на стіл [кинджал] убивці.|Catelyn kładzie na stole [sztylet] zabójcy.|Catelyn lays the assassin\'s [dagger] on the table.',
   'Його [лезо] зроблене з валірійської сталі.|Jego [ostrze] jest z valyriańskiej stali.|Its [blade] is made of Valyrian steel.',
   '[Руків\'я] прикрашене кісткою дракона.|[Rękojeść] jest ozdobiona smoczą kością.|The [handle] is decorated with dragonbone.',
   'Мізинець каже, що він колись був [власником] цього кинджала.|Littlefinger mówi, że był kiedyś [właścicielem] tego sztyletu.|Littlefinger says he was once the [owner] of this dagger.',
   'Він уклав [парі] на турнірі й поставив кинджал.|Założył się na turnieju i postawił sztylet w [zakładzie].|He made a [bet] at a tournament and staked the dagger.',
   'І він [програв] його Тіріонові Ланністеру.|I [przegrał] go z Tyrionem Lannisterem.|And he [lost] it to Tyrion Lannister.']),
  ('Що далі?|Co dalej?|What next?', 'помста|zemsta|revenge;розслідування|śledztwo|investigation;довіра|zaufanie|trust;доказ|dowód|proof;обіцяти|obiecać|to promise;прощатися|żegnać się|to say goodbye', [
   'Кейтлін хоче правди, але не [помсти].|Catelyn chce prawdy, ale nie [zemsty].|Catelyn wants the truth, not [revenge].',
   'Нед починає власне [розслідування].|Ned zaczyna własne [śledztwo].|Ned begins his own [investigation].',
   'Йому потрібен справжній [доказ], а не слова Мізинця.|Potrzebuje prawdziwego [dowodu], a nie słów Littlefingera.|He needs real [proof], not Littlefinger\'s word.',
   'Мізинець каже: «[Довіра] — це небезпечна річ».|Littlefinger mówi: „[Zaufanie] to niebezpieczna rzecz”.|Littlefinger says: “[Trust] is a dangerous thing.”',
   'Нед [обіцяє] дружині знайти правду.|Ned [obiecuje] żonie znaleźć prawdę.|Ned [promises] his wife he will find the truth.',
   'На світанку вони знову [прощаються].|O świcie znowu się [żegnają].|At dawn they [say] goodbye again.'])],
 rule={'uk': 'Нереальна умова в минулому (так не сталося): якби + минулий час → минулий час + би, а слова тоді, того дня, ще вранці показують, що мова про минуле: Якби Варис тоді не знайшов її, Нед не прийшов би так швидко. Змішані часи: умова в минулому, наслідок зараз: Якби Мізинець не програв кинджал, зараз він був би в нього.',
       'pl': 'Warunek nierealny w przeszłości (tak się nie stało): gdyby + forma -ł- → tryb przypuszczający, a słowa wtedy, tamtego dnia, rano pokazują przeszłość: Gdyby Varys wtedy jej nie znalazł, Ned nie przyszedłby tak szybko. Czasy mieszane: warunek w przeszłości, skutek teraz: Gdyby Littlefinger nie przegrał sztyletu, miałby go teraz.',
       'en': 'Third conditional: if + past perfect, would have + past participle, for an unreal past: If Varys hadn\'t found her, Ned wouldn\'t have come so quickly. Mixed conditional: past condition, present result: If Littlefinger hadn\'t lost the dagger, he would still have it now. Or present condition, past result: If Ned weren\'t so honest, he would have stayed in Winterfell.'},
 gram=['Якби Мізинець не програв кинджал, Тіріон [не мав би/не матиме/не має] його.|Gdyby Littlefinger nie przegrał sztyletu, Tyrion [nie miałby/nie będzie miał/nie ma] go.|If Littlefinger hadn\'t lost the dagger, Tyrion [wouldn\'t have had/won\'t have/doesn\'t have] it.',
  'Якби Бран тоді не поліз на вежу, він [не впав би/не впаде/не падає].|Gdyby Bran wtedy nie wspiął się na wieżę, [nie spadłby/nie spadnie/nie spada].|If Bran hadn\'t climbed the tower, he [wouldn\'t have fallen/won\'t fall/doesn\'t fall].',
  'Якби Кейтлін [не знайшла/не знайде/не знаходячи] волосину, вони б нічого не знали.|Gdyby Catelyn [nie znalazła/nie znajdzie/nie znajdując] włosa, nic by nie wiedzieli.|If Catelyn [hadn\'t found/won\'t find/doesn\'t find] the hair, they wouldn\'t have known anything.',
  'Якби вовк не стрибнув у вікно, Кейтлін [загинула б/загине/гине].|Gdyby wilk nie wskoczył przez okno, Catelyn [zginęłaby/zginie/ginie].|If the wolf hadn\'t jumped through the window, Catelyn [would have died/will die/dies].',
  'Якби Нед відмовився від посади, зараз він [був би/буде/є] вдома.|Gdyby Ned odmówił urzędu, [byłby/będzie/jest] teraz w domu.|If Ned had refused the post, he [would be/will be/is] at home now.',
  'Якби Ліза не [написала/напише/пише] того листа, Нед не шукав би правди.|Gdyby Lysa nie [napisała/napisze/pisze] tego listu, Ned nie szukałby prawdy.|If Lysa [hadn\'t written/won\'t write/doesn\'t write] that letter, Ned wouldn\'t be looking for the truth.',
  'Якби корабель тоді запізнився, Кейтлін [не застала б/не застане/не застає] Неда.|Gdyby statek wtedy się spóźnił, Catelyn [nie zastałaby/nie zastanie/nie zastaje] Neda.|If the ship had been late, Catelyn [wouldn\'t have found/won\'t find/doesn\'t find] Ned here.',
  'Якби Нед не був таким чесним, він [залишився б/залишиться/залишається] у Вінтерфеллі.|Gdyby Ned nie był tak uczciwy, [zostałby/zostanie/zostaje] w Winterfell.|If Ned weren\'t so honest, he [would have stayed/will stay/stays] in Winterfell.',
  'Якби ми [прийшли/прийдемо/приходячи] на годину пізніше, Кейтлін уже поїхала б.|Gdybyśmy [przyszli/przyjdziemy/przychodząc] godzinę później, Catelyn już by wyjechała.|If we [had arrived/will arrive/arrive] an hour later, Catelyn would have left.',
  'Якби Мізинець справді кохав Кейтлін, він [не брехав би/не бреше/не брехатиме] їй.|Gdyby Littlefinger naprawdę kochał Catelyn, [nie okłamywałby/nie okłamuje/nie będzie okłamywał] jej.|If Littlefinger really loved Catelyn, he [wouldn\'t have lied/won\'t lie/doesn\'t lie] to her.',
  'Якби Джон Аррен не помер, ми зараз [не були б/не будемо/не є] у столиці.|Gdyby Jon Arryn nie umarł, [nie bylibyśmy/nie będziemy/nie jesteśmy] teraz w stolicy.|If Jon Arryn hadn\'t died, we [wouldn\'t be/won\'t be/aren\'t] in the capital now.',
  'Якби ти не [приніс/принесеш/приносячи] свічку, ми б нічого не бачили.|Gdybyś nie [przyniósł/przyniesiesz/przynosząc] świecy, nic byśmy nie widzieli.|If you [hadn\'t brought/won\'t bring/don\'t bring] the candle, we wouldn\'t have seen a thing.'],
 rt='Таємна сторінка хроніки|Tajna strona kroniki|A secret page of the chronicle',
 read=['Цю сторінку я пишу [шифром], якого навчила мене леді Кейтлін.|Tę stronę piszę [szyfrem], którego nauczyła mnie lady Catelyn.|I am writing this page in the [code] Lady Catelyn taught me.',
  'Учора вночі ми [зустрілися] з нею в домі лорда Бейліша.|Wczoraj w nocy [spotkaliśmy się] z nią w domu lorda Baelisha.|Last night we [met] her in Lord Baelish\'s house.',
  'Якби Варис не попередив нас, ми б [не знали] про її приїзд.|Gdyby Varys nas nie ostrzegł, [nie wiedzielibyśmy] o jej przyjeździe.|If Varys hadn\'t warned us, we wouldn\'t have [known] she had arrived.',
  'Леді Кейтлін [привезла] кинджал убивці.|Lady Catelyn [przywiozła] sztylet zabójcy.|Lady Catelyn had [brought] the assassin\'s dagger.',
  'Лорд Бейліш одразу його [упізнав].|Lord Baelish od razu go [rozpoznał].|Lord Baelish [recognised] it at once.',
  'Він сказав, що кинджал колись [належав] йому.|Powiedział, że sztylet kiedyś [należał] do niego.|He said the dagger had once [belonged] to him.',
  'На турнірі він уклав парі і [програв] його.|Na turnieju założył się i go [przegrał].|At a tournament he made a bet and [lost] it.',
  'Переможцем був Тіріон [Ланністер].|Zwycięzcą był Tyrion [Lannister].|The winner was Tyrion [Lannister].',
  'Якби це була правда, Ланністери [хотіли б] смерті Брана.|Gdyby to była prawda, Lannisterowie [chcieliby] śmierci Brana.|If that were true, the Lannisters [would] want Bran dead.',
  'Але навіщо Тіріонові [вбивати] дитину?|Ale po co Tyrionowi [zabijać] dziecko?|But why would Tyrion want to [kill] a child?',
  'Лорд Нед не [вірить] лорду Бейлішу до кінця.|Lord Ned nie [ufa] lordowi Baelishowi do końca.|Lord Ned doesn\'t fully [trust] Lord Baelish.',
  'Він наказав мені [записувати] кожне слово радників.|Kazał mi [zapisywać] każde słowo doradców.|He has ordered me to [record] every word the councillors say.',
  'На світанку леді Кейтлін [вирушила] додому з сером Родріком.|O świcie lady Catelyn [wyruszyła] do domu z serem Rodrikiem.|At dawn Lady Catelyn [set] off for home with Ser Rodrik.',
  'Якби вона залишилася, її б [упізнали] Ланністери.|Gdyby została, [rozpoznaliby] ją Lannisterowie.|If she had stayed, the Lannisters would have [recognised] her.',
  'Тепер лорд Нед шукає, що відкрив Джон Аррен перед смертю.|Teraz lord Ned szuka tego, co odkrył Jon Arryn przed śmiercią.|Now Lord Ned is looking for what Jon Arryn discovered before he died.',
  'Якби ми знали це раніше, багато чого було б інакше.|Gdybyśmy wiedzieli to wcześniej, wiele byłoby inaczej.|If we had known this earlier, many things would have been different.'],
 chk=[('Де зустрілися Нед і Кейтлін?|Gdzie spotkali się Ned i Catelyn?|Where did Ned and Catelyn meet?', ['У домі Мізинця|W domu Littlefingera|In Littlefinger\'s house', 'У тронній залі|W sali tronowej|In the throne room', 'На кораблі|Na statku|On a ship']),
  ('Хто попередив їх про приїзд Кейтлін?|Kto ostrzegł ich o przyjeździe Catelyn?|Who warned them that Catelyn had arrived?', ['Варис|Varys|Varys', 'Ренлі|Renly|Renly', 'Король|Król|The king']),
  ('Як Мізинець утратив кинджал?|Jak Littlefinger stracił sztylet?|How did Littlefinger lose the dagger?', ['Програв у парі|Przegrał w zakładzie|He lost it in a bet', 'Його вкрали|Ukradziono go|It was stolen', 'Продав на ринку|Sprzedał na targu|He sold it at the market']),
  ('Кому він програв кинджал?|Komu przegrał sztylet?|Who did he lose the dagger to?', ['Тіріонові Ланністеру|Tyrionowi Lannisterowi|Tyrion Lannister', 'Джеймі Ланністеру|Jaimemu Lannisterowi|Jaime Lannister', 'Королю|Królowi|The king']),
  ('Чому Кейтлін поїхала на світанку?|Dlaczego Catelyn wyjechała o świcie?|Why did Catelyn leave at dawn?', ['Щоб її не впізнали|Żeby jej nie rozpoznano|So she wouldn\'t be recognised', 'Бо посварилася з Недом|Bo pokłóciła się z Nedem|Because she quarrelled with Ned', 'Бо її вигнав король|Bo wygnał ją król|Because the king banished her'])],
 qq='Перед від\'їздом Кейтлін просить тебе провести її до воріт. Вона йде швидко й питає тихо, щоб ніхто не почув.|Przed wyjazdem Catelyn prosi, żebyś odprowadził ją do bramy. Idzie szybko i pyta cicho, żeby nikt nie usłyszał.|Before she leaves, Catelyn asks you to walk her to the gates. She walks quickly and asks in a low voice so no one can hear.',
 quest=[('Кейтлін: Як ти думаєш, якби я залишилася вдома, Нед дізнався б правду?|Catelyn: Jak myślisz, gdybym została w domu, Ned poznałby prawdę?|Catelyn: Do you think that if I had stayed at home, Ned would have learned the truth?', 'Ні, міледі. Якби ви не приїхали, він би нічого не знав.|Nie, pani. Gdybyście nie przyjechali, nic by nie wiedział.|No, my lady. If you hadn\'t come, he wouldn\'t have known anything.', 'Ні, міледі. Якщо ви не приїхали, він не знатиме.|Nie, pani. Jeśli nie przyjechaliście, nie będzie wiedział.|No, my lady. If you didn\'t come, he won\'t know anything.'),
  ('Кейтлін: А якби Петир не впізнав кинджал?|Catelyn: A gdyby Petyr nie rozpoznał sztyletu?|Catelyn: And if Petyr hadn\'t recognised the dagger?', 'Тоді ми б досі шукали власника.|Wtedy wciąż szukalibyśmy właściciela.|Then we would still be looking for its owner.', 'Тоді ми шукатимемо б власника.|Wtedy będziemy szukaćby właściciela.|Then we will still looking for its owner.'),
  ('Кейтлін: Ти віриш Петирові?|Catelyn: Wierzysz Petyrowi?|Catelyn: Do you believe Petyr?', 'Якби я вірив усім, я б не дожив до сьогодні.|Gdybym wierzył wszystkim, nie dożyłbym dzisiejszego dnia.|If I believed everyone, I wouldn\'t have lived this long.', 'Якщо я вірив би всім, я доживу.|Jeśli wierzyłbym wszystkim, dożyję.|If I would believe everyone, I live long.'),
  ('Кейтлін: Що мені сказати Роббу?|Catelyn: Co mam powiedzieć Robbowi?|Catelyn: What shall I tell Robb?', 'Скажіть, що батько знайде правду, але Роббу треба бути готовим.|Powiedzcie, że ojciec znajdzie prawdę, ale Robb musi być gotowy.|Tell him his father will find the truth, but Robb must be ready.', 'Скажіть, що батько знайшов би правду, якщо Робб був.|Powiedzcie, że ojciec znalazłby prawdę, jeśli Robb był.|Tell him his father would found the truth.')],
 qend='Біля воріт Кейтлін зупиняється й тисне тобі руку. «Якби не ти, я б не довіряла нікому в цьому місті». Капюшон закриває її обличчя, і вона зникає в натовпі.|Przy bramie Catelyn się zatrzymuje i ściska ci dłoń. „Gdyby nie ty, nie ufałabym nikomu w tym mieście”. Kaptur zasłania jej twarz i znika w tłumie.|At the gates Catelyn stops and squeezes your hand. “If it weren\'t for you, I wouldn\'t trust anyone in this city.” Her hood hides her face, and she disappears into the crowd.',
 speak=['Якби Мізинець не програв кинджал, Тіріон не мав би його.|Gdyby Littlefinger nie przegrał sztyletu, Tyrion by go nie miał.|If Littlefinger hadn\'t lost the dagger, Tyrion wouldn\'t have had it.', 'Якби Нед відмовився, зараз він був би вдома.|Gdyby Ned odmówił, byłby teraz w domu.|If Ned had refused, he would be at home now.'],
 fin=('Напиши таємну сторінку хроніки (90+ слів): що було б, якби Кейтлін не приїхала, якби Мізинець не впізнав кинджал, якби Нед залишився у Вінтерфеллі? Що зараз було б інакше?|Napisz tajną stronę kroniki (90+ słów): co by było, gdyby Catelyn nie przyjechała, gdyby Littlefinger nie rozpoznał sztyletu, gdyby Ned został w Winterfell? Co byłoby teraz inaczej?|Write a secret page of the chronicle (90+ words): what would have happened if Catelyn hadn\'t come, if Littlefinger hadn\'t recognised the dagger, if Ned had stayed in Winterfell? What would be different now?',
      'Якби леді Кейтлін не приїхала,… Якби Мізинець не впізнав кинджал,… Якби лорд Нед залишився вдома, зараз він був би…|Gdyby lady Catelyn nie przyjechała,… Gdyby Littlefinger nie rozpoznał sztyletu,… Gdyby lord Ned został w domu, byłby teraz…|If Lady Catelyn hadn\'t come,… If Littlefinger hadn\'t recognised the dagger,… If Lord Ned had stayed at home, he would be… now.')), A)
